USE bandhkam_kamgar_db;
CREATE TABLE IF NOT EXISTS site_content (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,content_key VARCHAR(100) NOT NULL,language_code ENUM('mr','en') NOT NULL DEFAULT 'mr',title VARCHAR(255) NULL,body LONGTEXT NULL,is_published BOOLEAN NOT NULL DEFAULT TRUE,updated_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_site_content_key_language(content_key,language_code),CONSTRAINT fk_site_content_user FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS public_schemes (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name_mr VARCHAR(255) NOT NULL,name_en VARCHAR(255) NOT NULL,description_mr TEXT NULL,description_en TEXT NULL,benefit_amount VARCHAR(100) NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,display_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_public_schemes_active_order(is_active,display_order)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS feedback (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name VARCHAR(150) NOT NULL,mobile VARCHAR(20) NULL,feedback_type ENUM('feedback','complaint','problem','suggestion','review') NOT NULL,message TEXT NOT NULL,rating TINYINT UNSIGNED NULL,registration_number VARCHAR(100) NULL,status ENUM('open','in_progress','resolved','closed') NOT NULL DEFAULT 'open',internal_remark TEXT NULL,is_public BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_feedback_status_type(status,feedback_type)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gallery_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,category VARCHAR(100) NOT NULL,caption_mr VARCHAR(255) NULL,caption_en VARCHAR(255) NULL,image_path VARCHAR(500) NOT NULL,event_date DATE NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_gallery_category_active(category,is_active)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS news_announcements (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,title_mr VARCHAR(255) NOT NULL,title_en VARCHAR(255) NULL,content_mr TEXT NOT NULL,content_en TEXT NULL,category VARCHAR(100) NULL,publish_date DATE NOT NULL,expiry_date DATE NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,is_featured BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_news_publication(is_active,publish_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS festival_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,event_name VARCHAR(255) NOT NULL,message_mr TEXT NOT NULL,date_rule VARCHAR(100) NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,sms_enabled BOOLEAN NOT NULL DEFAULT FALSE,whatsapp_enabled BOOLEAN NOT NULL DEFAULT FALSE,display_on_website BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id)) ENGINE=InnoDB;
